    @staticmethod
    def _ride_type_matches(fare: Mapping[str, Any], expected: str) -> bool:
        normalized = normalize_text(expected).casefold()
        if not normalized:
            return True
        ride_tier = normalize_text(fare.get("rideTier")).casefold()
        ride_title = normalize_text(fare.get("rideTierTitle")).casefold()
        aliases = {
            "ridex": {"ridex", "x", "standard"},
            "ridexl": {"ridexl", "xl"},
        }.get(normalized, {normalized})
        return ride_tier in aliases or ride_title in aliases

    @staticmethod
    def _ticket_present(tickets: list[Any], expected: Mapping[str, Any]) -> bool:
        category = normalize_text(expected.get("category")).casefold()
        message = normalize_text(expected.get("message")).casefold()
        for ticket in tickets:
            if not isinstance(ticket, Mapping):
                continue
            ticket_category = normalize_text(ticket.get("category")).casefold()
            ticket_message = normalize_text(ticket.get("message")).casefold()
            if (not category or category == ticket_category) and (not message or message in ticket_message):
                return True
        return False

    @staticmethod
    def _wallet_favorited(payments: list[Any], expected: Mapping[str, Any]) -> bool:
        label = normalize_text(expected.get("label", "OpenDriver credits")).casefold()
        for payment in payments:
            if not isinstance(payment, Mapping):
                continue
            payment_label = normalize_text(payment.get("label")).casefold()
            if label and label != payment_label:
                continue
            return bool(payment.get("isDefault"))
        return False

