    @classmethod
    def _collect_scheduled_evidence(
        cls,
        *,
        backend: Mapping[str, Any],
        ui_text: str,
        params: Mapping[str, Any],
    ) -> dict[str, Any]:
        expected_user = params.get("expected_user") if isinstance(params.get("expected_user"), Mapping) else {}
        expected_rides = params.get("expected_scheduled_rides") if isinstance(params.get("expected_scheduled_rides"), list) else []
        expected_final = params.get("expected_final") if isinstance(params.get("expected_final"), Mapping) else {}

        responses = backend.get("responses") if isinstance(backend.get("responses"), Mapping) else {}
        me = OpenDriverRiderWorkflowEvaluator._data(responses.get("/users/me"))
        scheduled = OpenDriverRiderWorkflowEvaluator._data(responses.get("/rides/scheduled")).get("rides")
        history = OpenDriverRiderWorkflowEvaluator._data(responses.get("/rides/history")).get("rides")
        active = OpenDriverRiderWorkflowEvaluator._data(responses.get("/rides/active")).get("ride")
        payments = OpenDriverRiderWorkflowEvaluator._data(responses.get("/payments/methods")).get("paymentMethods")
        coupons = OpenDriverRiderWorkflowEvaluator._data(responses.get("/rider/coupons")).get("coupons")
        scheduled = scheduled if isinstance(scheduled, list) else []
        history = history if isinstance(history, list) else []
        payments = payments if isinstance(payments, list) else []
        coupons = coupons if isinstance(coupons, list) else []

        candidates: list[Mapping[str, Any]] = []
        for ride in scheduled:
            if isinstance(ride, Mapping):
                candidates.append(ride)
        for ride in history:
            if isinstance(ride, Mapping):
                candidates.append(ride)
        if isinstance(active, Mapping):
            candidates.append(active)

        user = me.get("user") if isinstance(me.get("user"), Mapping) else {}
        ui_text_norm = normalize_text(ui_text).casefold()
        final_page_tokens = [str(item) for item in expected_final.get("visible_text", []) if str(item)]
        final_page_visible = not final_page_tokens or all(
            normalize_text(item).casefold() in ui_text_norm for item in final_page_tokens
        )

        candidate_summaries = [cls._compact_scheduled_ride(ride) for ride in candidates]
        match_matrix: list[dict[str, Any]] = []
        matched: list[dict[str, Any]] = []
        used_indices: set[int] = set()
        for expected in expected_rides:
            if not isinstance(expected, Mapping):
                matched.append({"expected": expected, "matched": False, "reason": "expected ride is not an object"})
                continue
            candidate_checks: list[dict[str, Any]] = []
            match_index = None
            match_detail: dict[str, Any] = {}
            for index, ride in enumerate(candidates):
                detail = cls._match_ride(ride, expected, payments=payments, coupons=coupons)
                candidate_checks.append(
                    {
                        "candidate_index": index,
                        "candidate": cls._compact_scheduled_ride(ride),
                        "detail": detail,
                    }
                )
                if index in used_indices:
                    continue
                if detail["matched"]:
                    match_index = index
                    match_detail = detail
                    break
                if not match_detail:
                    match_detail = detail
            if match_index is None:
                matched.append({"expected": dict(expected), "matched": False, "best_unmatched_detail": match_detail})
            else:
                used_indices.add(match_index)
                matched.append(
                    {
                        "expected": dict(expected),
                        "matched": True,
                        "candidate_index": match_index,
                        "candidate": cls._compact_scheduled_ride(candidates[match_index]),
                        "detail": match_detail,
                    }
                )
            match_matrix.append(
                {
                    "expected": dict(expected),
                    "candidate_checks": candidate_checks,
                }
            )

        exact_or_min_count = int(params.get("expected_scheduled_count", len(expected_rides)) or 0)
        matched_count = sum(1 for item in matched if item.get("matched"))
        checks = {
            "rider_user_record_present": (
                normalize_text(user.get("role")).casefold() == "rider"
                and normalize_text(user.get("email")).casefold() == normalize_text(expected_user.get("email")).casefold()
            ),
            "expected_scheduled_ride_count_met": matched_count >= exact_or_min_count,
            "all_expected_scheduled_rides_matched": matched_count == len(expected_rides),
            "final_requested_page_visible": final_page_visible,
        }

        return {
            "checks": checks,
            "api_evidence": {
                "user": user,
                "scheduled_rides_count": len(scheduled),
                "history_rides_count": len(history),
                "active_ride_present": isinstance(active, Mapping) and bool(active.get("id")),
                "candidate_rides": candidate_summaries,
                "match_matrix": match_matrix,
                "matched_rides": matched,
                "payment_methods": payments,
                "coupons": coupons,
            },
            "ui_evidence": {
                "final_page_tokens": final_page_tokens,
                "ui_text_sample": normalize_text(ui_text)[:4000],
            },
        }

    @classmethod
    def _match_ride(
        cls,
        ride: Mapping[str, Any],
        expected: Mapping[str, Any],
        *,
        payments: list[Any],
        coupons: list[Any],
    ) -> dict[str, Any]:
        ride_text = flatten_text(ride).casefold()
        payment_text = flatten_text(payments).casefold()
        coupons_text = flatten_text(coupons).casefold()
        fare = ride.get("fareBreakdown") if isinstance(ride.get("fareBreakdown"), Mapping) else {}
        waypoints_text = flatten_text(ride.get("waypoints")).casefold()
        schedule_text = " ".join(
            normalize_text(ride.get(key))
            for key in ("scheduledFor", "scheduledUntil", "pickupTime", "scheduledWindow", "windowLabel")
            if ride.get(key) is not None
        ).casefold()

        pickup = normalize_text(expected.get("pickup")).casefold()
        destination = normalize_text(expected.get("destination")).casefold()
        stop = normalize_text(expected.get("stop")).casefold()
        ride_type = normalize_text(expected.get("ride_type"))
        promo = normalize_text(expected.get("promo_code")).casefold()
        payment = normalize_text(expected.get("payment")).casefold()
        date = normalize_text(expected.get("date")).casefold()
        window_start = normalize_text(expected.get("window_start")).casefold()

        checks = {
            "pickup_matches": (not pickup) or pickup in normalize_text(ride.get("pickupAddress")).casefold(),
            "destination_matches": (not destination) or destination in normalize_text(ride.get("destinationAddress")).casefold(),
            "stop_matches": (not stop) or stop in waypoints_text,
            "ride_type_matches": OpenDriverRiderWorkflowEvaluator._ride_type_matches(fare, ride_type) or normalize_text(ride_type).casefold() in ride_text,
            "date_matches": (not date) or date in schedule_text or date in ride_text,
            "window_start_matches": (not window_start) or window_start in schedule_text or window_start in ride_text,
            "promo_matches": (not promo) or promo in ride_text or promo in coupons_text,
            "payment_matches": (not payment) or payment in ride_text or payment in payment_text,
        }
        return {
            "matched": all(checks.values()),
            "checks": checks,
            "ride_id": ride.get("id"),
            "ride_text_sample": flatten_text(ride)[:2000],
        }

    @staticmethod
    def _compact_scheduled_ride(ride: Mapping[str, Any]) -> dict[str, Any]:
        fare = ride.get("fareBreakdown") if isinstance(ride.get("fareBreakdown"), Mapping) else {}
        return {
            "id": ride.get("id"),
            "status": ride.get("status"),
            "pickupAddress": ride.get("pickupAddress"),
            "destinationAddress": ride.get("destinationAddress"),
            "waypoints": ride.get("waypoints"),
            "scheduledFor": ride.get("scheduledFor"),
            "scheduledUntil": ride.get("scheduledUntil"),
            "rideTier": fare.get("rideTier"),
            "rideTierTitle": fare.get("rideTierTitle"),
            "promoCode": fare.get("promoCode"),
            "paymentStatus": ride.get("paymentStatus"),
        }


